fn is_ascii_digit(c: char) -> bool {
    // Returns true iff c is between '0' and '9' inclusive
    ('0'..='9').contains(&c)
}

fn all_digits(s: String) -> bool {
    // The empty string vacuously satisfies the predicate.
    // Otherwise, check that every Unicode code point in s is an ASCII digit.
    s.chars().all(is_ascii_digit)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_is_ascii_digit() {
        assert!(is_ascii_digit('0'));
        assert!(is_ascii_digit('5'));
        assert!(is_ascii_digit('9'));
        assert!(!is_ascii_digit('a'));
        assert!(!is_ascii_digit(' '));
        assert!(!is_ascii_digit('Ω')); // non-ASCII
    }

    #[test]
    fn test_all_digits_empty() {
        assert!(all_digits(String::new()));
    }

    #[test]
    fn test_all_digits_only_digits() {
        assert!(all_digits("0123456789".to_string()));
    }

    #[test]
    fn test_all_digits_mixed() {
        assert!(!all_digits("123a456".to_string()));
        assert!(!all_digits("123 456".to_string()));
        assert!(!all_digits("１２３４".to_string())); // fullwidth digits
    }
}